_legacyData.script:
let chatData = {content: "", whisper: ChatMessage.getWhisperRecipients("GM")}

let wounds = duplicate(this.actor.status.wounds)
let regen = (await new Roll("1d10").roll()).total

if (wounds.value >= wounds.max)
   return

if (wounds.value > 0)
{
   wounds.value += regen
   if (wounds.value > wounds.max) 
        wounds.value = wounds.max
   chatData.content += `<b>${this.actor.name}</b> regains ${regen} Wounds.`

    if (regen == 10)
       chatData.content += `<br>Additionally, they regenerate a Critical Wound.`
}
else if (regen >= 8)
{
    chatData.content += `<b>${this.actor.name}</b> rolled a ${regen} and regains 1 Wound.`
    wounds.value += 1
    if (regen == 10)
       chatData.content += `<br>Additionally, they regenerate a Critical Wound.`
}
else
{
    chatData.content += `<b>${this.actor.name}</b> Regenerate roll of ${regen} - No effect.`
}

this.actor.update({"data.status.wounds" : wounds})
ChatMessage.create(chatData)

